const AzkarModal: React.FC<AzkarModalProps> = ({ isOpen, onClose }) => {
  const [mode, setMode] = useState<TimeMode>('morning');
  const [completed, setCompleted] = useState<Set<string>>(new Set());

  // Set initial mode based on current time
  useEffect(() => {
    if (isOpen) {
      const hour = new Date().getHours();
      setMode(hour >= 5 && hour < 17 ? 'morning' : 'evening');
    }
  }, [isOpen]);

  // Prevent scrolling when open
  useEffect(() => {
    if (isOpen) document.body.style.overflow = 'hidden';
    else document.body.style.overflow = 'unset';
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  const toggleComplete = (id: string) => {
    const newCompleted = new Set(completed);
    if (newCompleted.has(id)) newCompleted.delete(id);
    else newCompleted.add(id);
    setCompleted(newCompleted);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-0 sm:p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className="relative bg-[#faf9f6] w-full sm:max-w-3xl h-full sm:h-[90vh] sm:rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header with Mode Toggle */}
        <div className={`px-6 py-4 border-b border-secondary-200 flex flex-col sm:flex-row gap-4 justify-between items-center transition-colors duration-500 ${mode === 'morning' ? 'bg-primary-50' : 'bg-slate-800 text-white'}`}>
          <div className="flex items-center gap-2">
            <h3 className={`text-xl font-bold font-serif ${mode === 'morning' ? 'text-primary-800' : 'text-primary-100'}`}>
              Azkar As-Sabah wal Masaa
            </h3>
          </div>

          <div className="flex bg-white/20 p-1 rounded-full backdrop-blur-sm border border-white/30">
             <button 
                onClick={() => setMode('morning')}
                className={`flex items-center gap-1 px-4 py-1.5 rounded-full text-sm font-medium transition-all ${mode === 'morning' ? 'bg-white text-orange-600 shadow-sm' : 'text-white/70 hover:text-white hover:bg-white/10'}`}
             >
                <Sun size={16} /> Morning
             </button>
             <button 
                onClick={() => setMode('evening')}
                className={`flex items-center gap-1 px-4 py-1.5 rounded-full text-sm font-medium transition-all ${mode === 'evening' ? 'bg-slate-700 text-indigo-300 shadow-sm' : 'text-slate-500 hover:text-slate-700 hover:bg-black/5'} ${mode === 'morning' ? 'text-slate-500' : ''}`}
             >
                <Moon size={16} /> Evening
             </button>
          </div>

          <button 
            onClick={onClose}
            className={`p-2 rounded-full transition-colors ${mode === 'morning' ? 'hover:bg-primary-100 text-primary-800' : 'hover:bg-slate-700 text-white'}`}
          >
            <X size={20} />
          </button>
        </div>

        {/* Scrollable List */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 scroll-smooth bg-[#faf9f6]">
          {adhkarData.map((dhikr) => {
            const isCompleted = completed.has(dhikr.id);
            const arabic = mode === 'morning' ? dhikr.arabicMorning : (dhikr.arabicEvening || dhikr.arabicMorning);
            const translit = mode === 'morning' ? dhikr.transliterationMorning : (dhikr.transliterationEvening || dhikr.transliterationMorning);
            const translation = mode === 'morning' ? dhikr.translationMorning : (dhikr.translationEvening || dhikr.translationMorning);

            return (
              <div 
                key={dhikr.id} 
                className={`bg-white rounded-xl border-2 transition-all duration-300 ${isCompleted ? 'border-primary-200 bg-primary-50/30' : 'border-secondary-100 shadow-sm hover:border-secondary-300'}`}
              >
                <div className="p-5">
                   {/* Header of Card */}
                   <div className="flex justify-between items-start mb-4">
                      <div>
                        <span className="inline-block px-2 py-0.5 rounded text-xs font-semibold tracking-wide bg-secondary-100 text-secondary-700 mb-1">
                          {dhikr.reference}
                        </span>
                        <h4 className="text-lg font-semibold text-slate-800">{dhikr.title}</h4>
                      </div>
                      <button 
                        onClick={() => toggleComplete(dhikr.id)}
                        className={`flex items-center justify-center w-8 h-8 rounded-full border transition-all ${isCompleted ? 'bg-primary-500 border-primary-500 text-white' : 'border-slate-300 text-slate-300 hover:border-primary-400 hover:text-primary-400'}`}
                        aria-label="Mark as read"
                      >
                         <Check size={16} strokeWidth={3} />
                      </button>
                   </div>

                   {/* Arabic Text */}
                   <div dir="rtl" className="mb-4">
                      <p className={`font-arabic text-2xl sm:text-3xl leading-[2.2] text-right ${mode === 'evening' ? 'text-slate-800' : 'text-slate-900'}`}>
                        {arabic}
                      </p>
                   </div>

                   {/* Count Pill */}
                   <div className="flex items-center gap-2 mb-4">
                      <span className="bg-slate-100 text-slate-600 text-xs font-bold px-3 py-1 rounded-full border border-slate-200">
                        {dhikr.count}x
                      </span>
                   </div>

                   {/* Translation details */}
                   <div className="space-y-2 border-t border-slate-100 pt-3">
                      <details className="group">
                        <summary className="list-none flex items-center cursor-pointer text-sm font-medium text-slate-500 hover:text-primary-600 transition-colors">
                           <ArrowRight size={14} className="mr-1 transition-transform group-open:rotate-90" />
                           View Translation & Transliteration
                        </summary>
                        <div className="mt-3 space-y-3 pl-4 border-l-2 border-slate-100 animate-in fade-in slide-in-from-top-1">
                           <div>
                              <p className="text-xs uppercase tracking-wider text-slate-400 mb-0.5">Transliteration</p>
                              <p className="text-sm text-slate-600 italic leading-relaxed">{translit}</p>
                           </div>
                           <div>
                              <p className="text-xs uppercase tracking-wider text-slate-400 mb-0.5">Meaning</p>
                              <p className="text-sm text-slate-800 leading-relaxed">{translation}</p>
                           </div>
                        </div>
                      </details>
                   </div>
                </div>
              </div>
            );
          })}

          <div className="flex justify-center pt-8 pb-4">
            <p className="text-slate-400 text-sm italic font-serif">End of {mode === 'morning' ? 'Morning' : 'Evening'} Adhkar</p>
          </div>
        </div>
      </div>
    </div>
  );
};

