const AzkarModal: React.FC<AzkarModalProps> = ({ isOpen, onClose }) => {
  const [activeTab, setActiveTab] = useState<Category>('daily');
  const [mode, setMode] = useState<TimeMode>('morning');
  const [completed, setCompleted] = useState<Set<string>>(new Set());

  // Set initial mode based on current time
  useEffect(() => {
    if (isOpen) {
      const hour = new Date().getHours();
      setMode(hour >= 5 && hour < 17 ? 'morning' : 'evening');
    }
  }, [isOpen]);

  // Prevent scrolling when open
  useEffect(() => {
    if (isOpen) document.body.style.overflow = 'hidden';
    else document.body.style.overflow = 'unset';
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  const toggleComplete = (id: string) => {
    const newCompleted = new Set(completed);
    if (newCompleted.has(id)) newCompleted.delete(id);
    else newCompleted.add(id);
    setCompleted(newCompleted);
  };

  const getActiveData = () => {
    switch (activeTab) {
      case 'daily': return dailyAdhkar;
      case 'wird': return specificWird;
      case 'hizb': return hizbs;
      case 'names': return asmaUlHusna;
      default: return dailyAdhkar;
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-0 sm:p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className="relative bg-[#faf9f6] w-full sm:max-w-4xl h-full sm:h-[90vh] sm:rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="bg-white border-b border-secondary-200">
          <div className="px-6 py-4 flex justify-between items-center">
             <div className="flex items-center gap-3">
               <h3 className="text-xl font-bold font-serif text-slate-800">
                 Dua & Adhkar Collection
               </h3>
             </div>
             <button 
                onClick={onClose}
                className="p-2 hover:bg-slate-100 rounded-full text-slate-500 hover:text-slate-800 transition-colors"
             >
               <X size={20} />
             </button>
          </div>

          {/* Navigation Tabs */}
          <div className="px-6 flex gap-6 overflow-x-auto scrollbar-hide">
             <button 
               onClick={() => setActiveTab('daily')}
               className={`pb-3 text-sm font-medium border-b-2 transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'daily' ? 'border-primary-600 text-primary-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
               <Sun size={16} /> Daily Adhkar
             </button>
             <button 
