               className={`pb-3 text-sm font-medium border-b-2 transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'wird' ? 'border-primary-600 text-primary-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
               <Hash size={16} /> Specific Wird
             </button>
             <button 
               onClick={() => setActiveTab('hizb')}
               className={`pb-3 text-sm font-medium border-b-2 transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'hizb' ? 'border-primary-600 text-primary-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
               <Shield size={16} /> Protection Hizbs
