                 <button 
                    onClick={() => setMode('morning')}
                    className={`flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold transition-all ${mode === 'morning' ? 'bg-white text-orange-600 shadow-sm' : 'text-white/70 hover:text-white hover:bg-white/10'}`}
                 >
                    <Sun size={14} /> AM
                 </button>
                 <button 
                    onClick={() => setMode('evening')}
                    className={`flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold transition-all ${mode === 'evening' ? 'bg-slate-700 text-indigo-300 shadow-sm' : 'text-slate-500 hover:text-slate-700 hover:bg-black/5'} ${mode === 'morning' ? 'text-slate-500' : ''}`}
                 >
                    <Moon size={14} /> PM
                 </button>
             </div>
          </div>
        )}

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 scroll-smooth bg-[#faf9f6]">
          {getActiveData().map((item) => {
            const isCompleted = completed.has(item.id);
            // Handle content switching based on mode for Daily tab
            const arabicText = (activeTab === 'daily' && mode === 'evening' && item.arabicEvening) 
              ? item.arabicEvening 
              : item.arabic;

            return (
              <div 
                key={item.id} 
                className={`bg-white rounded-xl border-2 transition-all duration-300 ${isCompleted ? 'border-primary-200 bg-primary-50/30' : 'border-secondary-100 shadow-sm hover:border-secondary-300'}`}
              >
                <div className="p-5">
                   <div className="flex justify-between items-start mb-4">
                      <div>
                        {item.reference && (
                          <span className="inline-block px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider bg-secondary-100 text-secondary-700 mb-1">
                            {item.reference}
                          </span>
                        )}
                        <h4 className="text-lg font-semibold text-slate-800">{item.title}</h4>
                      </div>
                      <button 
                        onClick={() => toggleComplete(item.id)}
                        className={`flex items-center justify-center w-8 h-8 rounded-full border transition-all ${isCompleted ? 'bg-primary-500 border-primary-500 text-white' : 'border-slate-300 text-slate-300 hover:border-primary-400 hover:text-primary-400'}`}
                        aria-label="Mark as read"
                      >
                         <Check size={16} strokeWidth={3} />
                      </button>
                   </div>

                   {/* Arabic Text */}
                   <div dir="rtl" className="mb-4">
                      <p className={`font-arabic text-2xl sm:text-3xl leading-[2.2] text-right ${activeTab === 'daily' && mode === 'evening' ? 'text-slate-800' : 'text-slate-900'}`}>
                        {arabicText}
                      </p>
                   </div>

                   {/* Count & Note */}
                   <div className="flex flex-wrap items-center gap-2 mb-4">
                      {item.count && (
                        <span className="bg-slate-100 text-slate-600 text-xs font-bold px-3 py-1 rounded-full border border-slate-200">
                          {item.count}x
                        </span>
                      )}
                      {item.note && (
                        <span className="text-xs text-slate-500 italic">
                          {item.note}
                        </span>
                      )}
                   </div>

                   {/* Translation */}
                   <div className="space-y-2 border-t border-slate-100 pt-3">
                      <details className="group">
                        <summary className="list-none flex items-center cursor-pointer text-sm font-medium text-slate-500 hover:text-primary-600 transition-colors">
                           <ArrowRight size={14} className="mr-1 transition-transform group-open:rotate-90" />
                           View Meaning
                        </summary>
                        <div className="mt-3 pl-4 border-l-2 border-slate-100 animate-in fade-in slide-in-from-top-1">
                           <p className="text-sm text-slate-800 leading-relaxed">{item.translation}</p>
                           {item.transliteration && (
                             <p className="text-sm text-slate-500 italic mt-2">{item.transliteration}</p>
                           )}
                        </div>
                      </details>
                   </div>
                </div>
              </div>
            );
          })}

          <div className="flex justify-center pt-8 pb-4">
            <p className="text-slate-400 text-sm italic font-serif">End of Section</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AzkarModal;
